package com.exelynt.booking.exception;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.AuthenticationException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant;
@RestControllerAdvice public class GlobalExceptionHandler { private ResponseEntity<ErrorResponse> response(HttpStatus status,String message,HttpServletRequest request){return ResponseEntity.status(status).body(new ErrorResponse(Instant.now(),status.value(),status.getReasonPhrase(),message,request.getRequestURI()));} @ExceptionHandler(ApiException.class) ResponseEntity<ErrorResponse> api(ApiException e,HttpServletRequest r){return response(e.status(),e.getMessage(),r);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> valid(MethodArgumentNotValidException e,HttpServletRequest r){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Validation failed");return response(HttpStatus.BAD_REQUEST,m,r);} @ExceptionHandler({HttpMessageNotReadableException.class,IllegalArgumentException.class}) ResponseEntity<ErrorResponse> bad(Exception e,HttpServletRequest r){return response(HttpStatus.BAD_REQUEST,"Malformed or invalid request",r);} @ExceptionHandler(AuthenticationException.class) ResponseEntity<ErrorResponse> unauthorized(AuthenticationException e,HttpServletRequest r){return response(HttpStatus.UNAUTHORIZED,"Invalid credentials",r);} @ExceptionHandler(AccessDeniedException.class) ResponseEntity<ErrorResponse> denied(AccessDeniedException e,HttpServletRequest r){return response(HttpStatus.FORBIDDEN,"Access denied",r);} @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> other(Exception e,HttpServletRequest r){return response(HttpStatus.INTERNAL_SERVER_ERROR,"Unexpected server error",r);} }
